    "CREATE TABLE \"measures\" (\n      id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), name TEXT NOT NULL,\n      unit TEXT NOT NULL, origin TEXT NOT NULL CHECK(origin IN ('taken','assembled','manual')),\n      kind TEXT NOT NULL CHECK(kind IN ('reading','running_total','period_count')),\n      timezone TEXT NOT NULL, period TEXT CHECK(period IN ('day','week','month')),\n      source_id TEXT REFERENCES measure_sources(id) ON DELETE RESTRICT,\n      formula TEXT CHECK(formula IS NULL OR json_valid(formula)),\n      definition_revision INTEGER NOT NULL CHECK(definition_revision>0),\n      write_revision INTEGER NOT NULL DEFAULT 0 CHECK(write_revision>=0), created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,\n      CHECK((origin='taken' AND source_id IS NOT NULL AND formula IS NULL) OR\n            (origin='assembled' AND source_id IS NULL AND formula IS NOT NULL) OR (origin='manual' AND source_id IS NULL AND formula IS NULL)))",
    "CREATE INDEX idx_measures_source ON measures(source_id,id)",
    "CREATE INDEX idx_measures_project ON measures(project_id,id)",
    "CREATE TABLE manual_measure_writes (\n      request_id TEXT PRIMARY KEY, measure_id TEXT NOT NULL REFERENCES measures(id) ON DELETE RESTRICT,\n      actor_kind TEXT NOT NULL, actor_id TEXT NOT NULL, payload_fingerprint TEXT NOT NULL,\n      date TEXT NOT NULL, value REAL NOT NULL,\n      write_revision INTEGER NOT NULL CHECK(write_revision>0), accepted_at INTEGER NOT NULL,\n      UNIQUE(measure_id,request_id))",
    'CREATE TABLE "measure_observations" (\n      measure_id TEXT NOT NULL REFERENCES measures(id) ON DELETE RESTRICT, date TEXT NOT NULL,\n      value REAL NOT NULL, run_id TEXT REFERENCES measure_source_runs(id) ON DELETE RESTRICT,\n      observed_at INTEGER NOT NULL, definition_revision INTEGER NOT NULL,\n      manual_write_id TEXT, period_start_date TEXT, period_end_date_exclusive TEXT, query_start_at REAL, query_end_at REAL, limitation TEXT,\n      CHECK((period_start_date IS NULL)=(period_end_date_exclusive IS NULL)),\n      CHECK((run_id IS NOT NULL)+(manual_write_id IS NOT NULL)=1), FOREIGN KEY(measure_id,manual_write_id) REFERENCES manual_measure_writes(measure_id,request_id) ON DELETE RESTRICT, PRIMARY KEY(measure_id,date))',
    "CREATE TABLE \"credentials\" (\n      id TEXT PRIMARY KEY, scheme TEXT NOT NULL CHECK(scheme='local'), name TEXT NOT NULL,\n      auth_kind TEXT NOT NULL CHECK(auth_kind IN ('bearer','header','basic')),\n      encryption_version INTEGER NOT NULL CHECK(encryption_version IN (1,2)),\n      encryption_context BLOB NOT NULL, nonce BLOB NOT NULL, ciphertext BLOB NOT NULL,\n      revision INTEGER NOT NULL CHECK(revision>0),\n      created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)",
    "CREATE INDEX credentials_reference ON credentials(scheme,name)",
    "CREATE TABLE credential_requests (\n        request_id TEXT PRIMARY KEY,\n        conversation_id TEXT NOT NULL REFERENCES conversations(conversation_id) ON DELETE CASCADE,\n        requester_kind TEXT NOT NULL, requester_id TEXT NOT NULL,\n        request_json TEXT NOT NULL, body TEXT NOT NULL,\n        created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL\n    )",
    "CREATE INDEX credential_requests_conversation ON credential_requests(conversation_id)",
    "CREATE TABLE credential_request_delivery_attempts (\n        attempt_id TEXT PRIMARY KEY,\n        request_id TEXT NOT NULL REFERENCES credential_requests(request_id) ON DELETE CASCADE,\n        sender_message_id TEXT NOT NULL UNIQUE,\n        prompt TEXT NOT NULL, status TEXT NOT NULL, refusal_reason TEXT,\n        created_at INTEGER NOT NULL\n    )",
    "CREATE INDEX credential_request_attempts_request ON credential_request_delivery_attempts(request_id,created_at)",
    "CREATE TABLE datasets (\n          id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id),\n          source_id TEXT NOT NULL REFERENCES measure_sources(id) ON DELETE RESTRICT,\n          name TEXT NOT NULL, timezone TEXT NOT NULL,\n          dimensions TEXT NOT NULL CHECK(json_valid(dimensions)),\n          fields TEXT NOT NULL CHECK(json_valid(fields)),\n          definition_revision INTEGER NOT NULL CHECK(definition_revision>0),\n          created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL)",
    "CREATE TABLE dataset_results (\n          dataset_id TEXT NOT NULL REFERENCES datasets(id) ON DELETE RESTRICT,\n          date TEXT NOT NULL, run_id TEXT NOT NULL REFERENCES measure_source_runs(id) ON DELETE RESTRICT,\n          definition_revision INTEGER NOT NULL CHECK(definition_revision>0),\n          output TEXT NOT NULL CHECK(json_valid(output)),\n          collected_at INTEGER NOT NULL, query_end_at REAL NOT NULL, query_start_at REAL,\n          unavailable_reason TEXT, limitation TEXT, PRIMARY KEY(dataset_id,date))",
    "CREATE TABLE dataset_rows (\n          dataset_id TEXT NOT NULL, date TEXT NOT NULL, dimension_key TEXT NOT NULL,\n          dimensions TEXT NOT NULL CHECK(json_valid(dimensions)),\n          field_values TEXT NOT NULL CHECK(json_valid(field_values)),\n          PRIMARY KEY(dataset_id,date,dimension_key),\n          FOREIGN KEY(dataset_id,date) REFERENCES dataset_results(dataset_id,date) ON DELETE CASCADE)",
    "CREATE TABLE dataset_category_labels (\n          dataset_id TEXT NOT NULL REFERENCES datasets(id) ON DELETE RESTRICT,\n          dimension TEXT NOT NULL, code TEXT NOT NULL, label TEXT NOT NULL,\n          PRIMARY KEY(dataset_id,dimension,code))",
    "CREATE INDEX idx_datasets_project ON datasets(project_id,id)",
    "CREATE INDEX idx_datasets_source ON datasets(source_id,id)",
    "CREATE TABLE \"measure_sources\" (\n      id TEXT PRIMARY KEY, name TEXT NOT NULL, project_id TEXT NOT NULL REFERENCES projects(id),\n      account TEXT NOT NULL,\n      responsible_kind TEXT NOT NULL CHECK(responsible_kind IN ('chief','manager','goal')),\n      responsible_manager_id TEXT REFERENCES managers(id) ON DELETE RESTRICT, responsible_goal_id TEXT REFERENCES goals(id) ON DELETE RESTRICT,\n      responsibility_revision INTEGER NOT NULL CHECK(responsibility_revision>0),\n      enabled INTEGER NOT NULL DEFAULT 0 CHECK(enabled IN (0,1)), local_time TEXT,\n      source_revision INTEGER NOT NULL CHECK(source_revision>0),\n      script_revision_counter INTEGER NOT NULL DEFAULT 0 CHECK(script_revision_counter>=0),\n      active_script TEXT, active_script_revision INTEGER, active_script_sha256 TEXT,\n      active_script_author_kind TEXT, active_script_author_id TEXT, active_script_created_at INTEGER,\n      created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,\n      CHECK((responsible_kind='chief' AND responsible_manager_id IS NULL AND responsible_goal_id IS NULL) OR\n            (responsible_kind='manager' AND responsible_manager_id IS NOT NULL AND responsible_goal_id IS NULL) OR (responsible_kind='goal' AND responsible_manager_id IS NULL AND responsible_goal_id IS NOT NULL)),\n      CHECK((active_script IS NULL AND active_script_revision IS NULL AND active_script_sha256 IS NULL\n             AND active_script_author_kind IS NULL AND active_script_author_id IS NULL AND active_script_created_at IS NULL) OR\n            (active_script IS NOT NULL AND active_script_revision IS NOT NULL AND active_script_sha256 IS NOT NULL\n             AND active_script_author_kind IS NOT NULL AND active_script_author_id IS NOT NULL AND active_script_created_at IS NOT NULL)),\n      CHECK(enabled=0 OR (active_script IS NOT NULL AND local_time IS NOT NULL)))",
    "CREATE INDEX idx_measure_sources_slot ON measure_sources(enabled,local_time,id)",
    "CREATE INDEX idx_measure_sources_project ON measure_sources(project_id,id)",
    "CREATE TABLE \"manager_wakes\" (id INTEGER PRIMARY KEY AUTOINCREMENT,manager_id TEXT,ticket_id TEXT REFERENCES tickets(id) ON DELETE SET NULL,source_kind TEXT NOT NULL CHECK (source_kind IN ('proposal','worker_error','turn_failure','source_failure')),source_revision INTEGER NOT NULL CHECK (source_revision > 0),summary TEXT NOT NULL,created_at INTEGER NOT NULL,closed_at INTEGER,target_kind TEXT NOT NULL CHECK (target_kind IN ('chief','manager','ticket','goal')),target_id TEXT NOT NULL,source_conversation_id TEXT, measure_source_id TEXT REFERENCES measure_sources(id) ON DELETE RESTRICT, source_episode INTEGER, source_responsibility_revision INTEGER)",
