    'CREATE TRIGGER "resource_chief_settings_insert" AFTER INSERT ON "chief_settings" WHEN 1 BEGIN INSERT INTO resource_source_versions(source_kind,source_id,revision) VALUES (\'chief-settings\',NEW.employee_id,1) ON CONFLICT(source_kind,source_id) DO UPDATE SET revision=revision+1; END',
    'CREATE TRIGGER "resource_chief_settings_update" AFTER UPDATE ON "chief_settings" WHEN OLD.label IS NOT NEW.label OR OLD.recap IS NOT NEW.recap OR OLD.employee_backend IS NOT NEW.employee_backend OR OLD.employee_launch_model IS NOT NEW.employee_launch_model OR OLD.employee_launch_reasoning_effort IS NOT NEW.employee_launch_reasoning_effort BEGIN INSERT INTO resource_source_versions(source_kind,source_id,revision) VALUES (\'chief-settings\',NEW.employee_id,1) ON CONFLICT(source_kind,source_id) DO UPDATE SET revision=revision+1; END',
    'CREATE TRIGGER "resource_chief_settings_delete" AFTER DELETE ON "chief_settings" WHEN 1 BEGIN INSERT INTO resource_source_versions(source_kind,source_id,revision) VALUES (\'chief-settings\',OLD.employee_id,1) ON CONFLICT(source_kind,source_id) DO UPDATE SET revision=revision+1; END',
