    'CREATE TRIGGER "resource_chief_launch_delete" AFTER DELETE ON "chief_settings" WHEN 1 BEGIN INSERT INTO resource_source_versions(source_kind,source_id,revision) VALUES (\'chief-launch\',OLD.employee_id,1) ON CONFLICT(source_kind,source_id) DO UPDATE SET revision=revision+1; END',
