    'CREATE TRIGGER "resource_workspace_blockers_update" AFTER UPDATE ON "ticket_blocks" WHEN 1 BEGIN INSERT INTO resource_source_versions(source_kind,source_id,revision) VALUES (\'workspace-blockers\',NEW.blocked_ticket_id,1) ON CONFLICT(source_kind,source_id) DO UPDATE SET revision=revision+1; END',
