    "CREATE TRIGGER ticket_workspace_fields_insert AFTER INSERT ON tickets BEGIN\n        INSERT INTO ticket_workspace_fields\n        SELECT NEW.id, fields.key, 1, length(CAST(fields.value AS BLOB))\n        FROM json_each(NEW.field_values) fields;\n    END",
    "CREATE TRIGGER ticket_workspace_fields_update\n        AFTER UPDATE OF field_values ON tickets WHEN OLD.field_values IS NOT NEW.field_values BEGIN\n        INSERT INTO ticket_workspace_fields\n        SELECT NEW.id, fields.key, 1, length(CAST(fields.value AS BLOB))\n        FROM json_each(NEW.field_values) fields\n        LEFT JOIN json_each(OLD.field_values) prior ON prior.key=fields.key\n        WHERE prior.value IS NOT fields.value\n        ON CONFLICT(ticket_id,field) DO UPDATE SET\n            revision=revision+1,byte_count=excluded.byte_count;\n        UPDATE ticket_workspace_fields SET revision=revision+1,byte_count=0\n        WHERE ticket_id=NEW.id AND field IN (\n            SELECT prior.key FROM json_each(OLD.field_values) prior\n            WHERE NOT EXISTS (SELECT 1 FROM json_each(NEW.field_values) next\n                WHERE next.key=prior.key)\n        );\n    END",
    "CREATE TRIGGER artifact_links_insert AFTER INSERT ON tickets BEGIN INSERT OR IGNORE INTO ticket_artifact_link_dirty SELECT NEW.id,j.key FROM json_each(NEW.field_values) j; INSERT OR IGNORE INTO ticket_artifact_link_dirty SELECT NEW.id,'@proposal' WHERE 1; END",
    "CREATE TRIGGER artifact_links_update AFTER UPDATE ON tickets WHEN OLD.field_values IS NOT NEW.field_values OR OLD.pending_proposal IS NOT NEW.pending_proposal BEGIN INSERT OR IGNORE INTO ticket_artifact_link_dirty SELECT NEW.id,j.key FROM json_each(NEW.field_values) j WHERE json_extract(OLD.field_values,'$.' || json_quote(j.key)) IS NOT j.value; INSERT OR IGNORE INTO ticket_artifact_link_dirty SELECT NEW.id,'@proposal' WHERE OLD.pending_proposal IS NOT NEW.pending_proposal; END",
    "CREATE TRIGGER artifact_links_deleted_fields AFTER UPDATE OF field_values ON tickets BEGIN INSERT OR IGNORE INTO ticket_artifact_link_dirty SELECT NEW.id,j.key FROM json_each(OLD.field_values) j WHERE json_type(NEW.field_values,'$.' || json_quote(j.key)) IS NULL; END",
    "CREATE TRIGGER history_revision_insert AFTER INSERT ON conversation_history_catalog BEGIN INSERT INTO resource_source_versions VALUES('conversation-history',NEW.owner_kind || ':' || NEW.owner_id,1) ON CONFLICT(source_kind,source_id) DO UPDATE SET revision=revision+1; END",
    "CREATE TRIGGER history_revision_delete AFTER DELETE ON conversation_history_catalog BEGIN INSERT INTO resource_source_versions VALUES('conversation-history',OLD.owner_kind || ':' || OLD.owner_id,1) ON CONFLICT(source_kind,source_id) DO UPDATE SET revision=revision+1; END",
